/* mapics — frontend logic
 *
 * Loads data.json (generated by `npm run build`), drops each geotagged photo onto
 * a Leaflet + OpenStreetMap map. Photos are clustered into dots when zoomed out and
 * become photo thumbnails as you zoom in. Clicking a thumbnail opens the photo as a
 * polaroid with its caption.
 */

const THUMBNAIL_ZOOM = 13; // at/above this zoom, individual pins show as photo thumbnails
const DATA_URL = "data.json";

// Whole-world bounds — the map covers the entire globe, clamped to the Web
// Mercator latitude limits and to a single (non-repeating) world copy so
// zooming out stays consistent instead of tiling endlessly sideways.
const WORLD_BOUNDS = L.latLngBounds([-85.05, -180], [85.05, 180]);

const map = L.map("map", {
  zoomControl: true,
  maxBounds: WORLD_BOUNDS,
  maxBoundsViscosity: 1.0, // firmly resist panning off the world
});

L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
  maxZoom: 19,
  noWrap: true,
  bounds: WORLD_BOUNDS,
  attribution:
    '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
}).addTo(map);

/**
 * Smallest zoom at which one (non-repeating) world still covers the whole
 * viewport. Below it the map background would show through as empty bands on
 * the sides — so this becomes the map's minZoom and is re-applied on resize.
 */
function worldFillZoom() {
  const size = map.getSize();
  const worldPx = map.options.crs.scale(0); // world width/height in px at zoom 0
  return Math.ceil(Math.log2(Math.max(size.x, size.y) / worldPx));
}

function applyWorldFillZoom() {
  const min = Math.max(0, worldFillZoom());
  map.setMinZoom(min);
  if (map.getZoom() < min) map.setZoom(min);
}

applyWorldFillZoom();
map.on("resize", applyWorldFillZoom);

// Default view: the whole world until photo data loads.
map.fitWorld();

// ---- Polaroid modal ---------------------------------------------------------

const overlay = document.getElementById("polaroid-overlay");
const polaroidPhoto = document.getElementById("polaroid-photo");
const polaroidMessage = document.getElementById("polaroid-message");
const polaroidMeta = document.getElementById("polaroid-meta");
const polaroidSong = document.getElementById("polaroid-song");

function formatMeta(photo) {
  const parts = [];
  if (photo.date) {
    const d = new Date(photo.date);
    if (!Number.isNaN(d.getTime())) {
      parts.push(
        d.toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" })
      );
    }
  }
  parts.push(`${photo.lat.toFixed(4)}, ${photo.lng.toFixed(4)}`);
  return parts.join(" · ");
}

/**
 * Build an embeddable player for a song URL.
 * Supports Spotify (track/album/playlist/episode) and YouTube / YouTube Music as
 * inline iframes; anything else falls back to a "Listen" link.
 * Returns an HTML string, or "" if no usable URL.
 */
function renderSong(url) {
  if (!url) return "";
  let u;
  try {
    u = new URL(url);
  } catch {
    return "";
  }
  const host = u.hostname.replace(/^www\./, "");

  // Spotify → compact embed player
  if (host === "open.spotify.com") {
    const m = u.pathname.match(/\/(track|album|playlist|episode|artist)\/([A-Za-z0-9]+)/);
    if (m) {
      const src = `https://open.spotify.com/embed/${m[1]}/${m[2]}`;
      return `<iframe class="song-embed song-spotify" src="${src}" width="100%" height="80"
        frameborder="0" loading="lazy" allow="encrypted-media; clipboard-write"></iframe>`;
    }
  }

  // YouTube / YouTube Music → embed player
  let ytId = null;
  if (host === "youtu.be") {
    ytId = u.pathname.slice(1);
  } else if (host === "youtube.com" || host === "m.youtube.com" || host === "music.youtube.com") {
    ytId = u.searchParams.get("v");
  }
  if (ytId) {
    const src = `https://www.youtube-nocookie.com/embed/${encodeURIComponent(ytId)}`;
    return `<iframe class="song-embed song-youtube" src="${src}" width="100%" height="80"
      frameborder="0" loading="lazy"
      allow="encrypted-media; picture-in-picture" allowfullscreen></iframe>`;
  }

  // Fallback: a plain link
  return `<a class="song-link" href="${u.href}" target="_blank" rel="noopener noreferrer">🎵 Listen</a>`;
}

function openPolaroid(photo) {
  polaroidPhoto.src = photo.full;
  polaroidPhoto.alt = photo.caption || photo.file;
  polaroidMessage.textContent = photo.caption || "";
  polaroidMeta.textContent = formatMeta(photo);

  const songHtml = renderSong(photo.song);
  polaroidSong.innerHTML = songHtml;
  polaroidSong.classList.toggle("hidden", !songHtml);

  overlay.classList.remove("hidden");
  // Trigger the entrance animation.
  requestAnimationFrame(() => overlay.classList.add("visible"));
}

function closePolaroid() {
  overlay.classList.remove("visible");
  overlay.addEventListener(
    "transitionend",
    () => {
      overlay.classList.add("hidden");
      polaroidPhoto.src = "";
      polaroidSong.innerHTML = ""; // stop any playing embed
    },
    { once: true }
  );
}

document.getElementById("polaroid-close").addEventListener("click", closePolaroid);
overlay.addEventListener("click", (e) => {
  if (e.target === overlay) closePolaroid();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !overlay.classList.contains("hidden")) closePolaroid();
});

// ---- Markers ----------------------------------------------------------------

function makeThumbIcon(photo) {
  return L.divIcon({
    className: "photo-pin",
    html: `<div class="photo-pin-inner"><img src="${photo.thumb}" alt="" loading="lazy" /></div>`,
    iconSize: [56, 56],
    iconAnchor: [28, 62], // bottom-center tip
    popupAnchor: [0, -60],
  });
}

function makeDotIcon() {
  return L.divIcon({
    className: "photo-dot",
    html: '<span class="photo-dot-pin"></span>',
    iconSize: [30, 40],
    iconAnchor: [15, 38], // tip of the teardrop
    popupAnchor: [0, -36],
  });
}

function iconForZoom(photo, zoom) {
  return zoom >= THUMBNAIL_ZOOM ? makeThumbIcon(photo) : makeDotIcon();
}

async function init() {
  let photos = [];
  try {
    const res = await fetch(DATA_URL, { cache: "no-cache" });
    if (res.ok) photos = await res.json();
  } catch {
    /* data.json missing → empty state */
  }

  if (!Array.isArray(photos) || photos.length === 0) {
    document.getElementById("empty-state").classList.remove("hidden");
    return;
  }

  const cluster = L.markerClusterGroup({
    showCoverageOnHover: false,
    maxClusterRadius: 50,
    spiderfyOnMaxZoom: true,
    iconCreateFunction(clusterObj) {
      const count = clusterObj.getChildCount();
      return L.divIcon({
        className: "photo-cluster",
        html: `<div class="photo-cluster-inner"><span>${count}</span></div>`,
        iconSize: [44, 44],
      });
    },
  });

  const markers = [];
  for (const photo of photos) {
    const marker = L.marker([photo.lat, photo.lng], {
      icon: iconForZoom(photo, map.getZoom()),
      title: photo.caption || photo.file,
    });
    marker.photo = photo;
    marker.on("click", () => openPolaroid(photo));
    markers.push(marker);
    cluster.addLayer(marker);
  }
  map.addLayer(cluster);

  // Swap dot <-> thumbnail icons when the zoom threshold is crossed.
  let lastMode = map.getZoom() >= THUMBNAIL_ZOOM ? "thumb" : "dot";
  map.on("zoomend", () => {
    const mode = map.getZoom() >= THUMBNAIL_ZOOM ? "thumb" : "dot";
    if (mode === lastMode) return;
    lastMode = mode;
    for (const marker of markers) {
      marker.setIcon(iconForZoom(marker.photo, map.getZoom()));
    }
  });

  // Fit to all photos.
  const bounds = L.latLngBounds(photos.map((p) => [p.lat, p.lng]));
  map.fitBounds(bounds, { padding: [60, 60], maxZoom: 15 });
}

init();
